sections.css:
.bcn-search-trigger .esa-icon {
  flex: none;
  color: var(--color-text-tertiary);
}
.bcn-help-bar .esa-icon-button {
  color: var(--bcn-helpbar-fg-muted);
  --icon-button-bg-hover: var(--bcn-helpbar-hover-bg);
}
.bcn-help-bar .esa-icon-button:hover,
.bcn-help-bar .esa-icon-button:focus-visible {
  color: var(--bcn-helpbar-fg);
}
.bcn-gd__label .esa-icon {
  color: var(--color-text-tertiary);
  flex: none;
}
.bcn-gd-row .esa-icon {
  color: var(--color-text-tertiary);
  flex: none;
}
.topbar__right .esa-icon-button {
  color: var(--color-text-secondary);
}
.user-panel__item .esa-icon {
  color: var(--bcn-gray-500);
}
.user-panel__item--danger .esa-icon {
  color: var(--color-danger);
}
.project-switcher__trigger > .esa-icon:first-child {
  flex-shrink: 0;
  color: var(--bcn-gray-500);
}
.nav-section__header:hover .esa-icon,
.nav-section--active .nav-section__header,
.nav-section--active .nav-section__header .esa-icon {
  color: var(--color-primary);
}
.nav-section__header > .esa-icon:first-child {
  flex-shrink: 0;
  color: var(--bcn-gray-950);
  transition: color 0.15s ease;
}
.nav-section__header > .esa-icon:last-child {
  color: var(--bcn-gray-400);
  transition:
    transform 0.15s ease,
    opacity 0.2s ease-in-out;
  flex-shrink: 0;
}
.nav-section--collapsed .nav-section__header > .esa-icon:last-child {
  transform: rotate(-90deg);
}
.side-nav.collapsed .nav-section__header > .esa-icon:last-child {
  display: none;
}
.bcn-phome {
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
}
.bcn-phome__cover {
  position: relative;
  height: 132px;
  overflow: hidden;
  background: var(--color-surface-sunken);
}
.bcn-phome__hero {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.bcn-phome__body {
  display: flex;
  align-items: flex-start;
  gap: var(--spacing-500);
  padding: 0 var(--spacing-600) var(--spacing-500);
}
.bcn-phome__edit {
  position: absolute;
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-150);
  padding: var(--spacing-150) var(--spacing-250);
  font-family: inherit;
  font-size: 0.8125rem;
  font-weight: var(--font-weight-semibold);
  color: var(--color-text-primary);
  background: color-mix(in srgb, var(--color-surface) 92%, transparent);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-100);
  cursor: pointer;
  opacity: 0;
  transition: opacity 0.15s ease;
}
.bcn-phome__edit--cover {
  top: var(--spacing-300);
  right: var(--spacing-600);
}
.bcn-phome__cover:hover .bcn-phome__edit--cover,
.bcn-phome__edit--cover:focus-visible {
  opacity: 1;
}
.bcn-phome__sealwrap {
  position: relative;
  flex-shrink: 0;
}
.bcn-phome__edit--logo {
  right: 0;
  bottom: 0;
  padding: var(--spacing-150);
  border-radius: var(--radius-full);
}
.bcn-phome__sealwrap:hover .bcn-phome__edit--logo,
.bcn-phome__edit--logo:focus-visible {
  opacity: 1;
}
.bcn-phome__seal {
  display: block;
  flex-shrink: 0;
  width: 92px;
  height: 92px;
  margin-top: -46px;
  border-radius: var(--radius-full);
  background: var(--color-surface);
  border: 3px solid var(--color-surface);
  object-fit: contain;
  box-shadow: var(--shadow-100, 0 2px 12px 0 rgba(0, 0, 0, 0.08));
}
.bcn-phome__id {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-200);
  padding-top: var(--spacing-400);
  min-width: 0;
  flex: 1;
}
.bcn-phome__idtop {
  display: flex;
  align-items: center;
  gap: var(--spacing-300);
  flex-wrap: wrap;
}
.bcn-phome__name {
  margin: 0;
  font-family: var(--font-decorative, var(--font-display, var(--font-sans)));
  font-weight: var(--font-weight-bold);
  font-size: var(--type-size-600);
  line-height: var(--line-height-tight);
  letter-spacing: var(--letter-spacing-tight);
  color: var(--bcn-gray-1000, var(--color-text-primary));
}
.bcn-phome__eyebrow {
  margin: 0 0 var(--spacing-200);
  font-size: var(--type-size-150);
  font-weight: var(--font-weight-medium);
  color: var(--color-text-tertiary);
}
.bcn-mod__link .esa-icon {
  color: var(--color-text-muted);
}
.bcn-status-chip {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-150);
  padding: 2px var(--spacing-250);
  border-radius: var(--radius-full);
  font-size: var(--type-size-100);
  font-weight: var(--font-weight-semibold);
  white-space: nowrap;
  background: color-mix(in srgb, var(--_chip) 16%, transparent);
  color: color-mix(in srgb, var(--_chip) 72%, #1a1a1a);
}
.bcn-status-chip__dot {
  width: 8px;
  height: 8px;
  border-radius: var(--radius-full);
  background: var(--_chip);
  flex-shrink: 0;
}
.esa-icon-button {
  --_ib-size: var(--form-height-md, 40px);
  --_ib-bg-hover: var(
    --icon-button-bg-hover,
    color-mix(in srgb, currentColor 14%, transparent)
  );
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--_ib-size);
  height: var(--_ib-size);
  padding: 0;
  border: 0;
  border-radius: var(--radius-200, 8px);
  background: transparent;
  color: inherit;
  cursor: pointer;
  transition: background var(--transition-fast, 0.15s ease);
  -webkit-appearance: none;
  appearance: none;
}
.esa-icon-button--xs {
  --_ib-size: var(--form-height-xs, 28px);
}
.esa-icon-button--sm {
  --_ib-size: var(--form-height-sm, 32px);
}
.esa-icon-button--lg {
  --_ib-size: var(--form-height-lg, 48px);
}
.esa-icon-button:hover {
  background: var(--_ib-bg-hover);
}
.esa-icon-button:focus-visible {
  outline: var(--focus-ring-width) solid currentColor;
  outline-offset: var(--focus-ring-offset, 2px);
}
.esa-icon {
  --_icon-size: var(--icon-size-md, var(--icon-size-medium, 20px));
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--_icon-size);
  height: var(--_icon-size);
  line-height: 1;
  color: inherit;
}
.esa-icon--xs {
  --_icon-size: var(--icon-size-xs, 14px);
}
.esa-icon--sm {
  --_icon-size: var(--icon-size-sm, var(--icon-size-small, 16px));
}
.esa-icon--md {
  --_icon-size: var(--icon-size-md, var(--icon-size-medium, 20px));
}
.esa-icon--lg {
  --_icon-size: var(--icon-size-lg, var(--icon-size-large, 24px));
}
.esa-icon--xl {
  --_icon-size: var(--icon-size-xl, 28px);
}
.esa-icon svg {
  display: block;
  width: var(--_icon-size);
  height: var(--_icon-size);
}
.breadcrumbs__items .esa-icon {
  color: var(--bcn-gray-400);
}
.page-layout__title h1 .esa-icon {
  color: var(--bcn-gray-1000);
  flex-shrink: 0;
}

.bcn-tl__head {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-400);
}
.bcn-tl__full {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-100);
  font-size: var(--type-size-150);
  font-weight: var(--font-weight-semibold);
  color: var(--color-primary);
  text-decoration: none;
  white-space: nowrap;
}
.bcn-tl__full:hover {
  color: var(--color-primary-hover);
}
.bcn-tl {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-250);
}
.bcn-tl__row {
  display: grid;
  grid-template-columns: 5.5rem 1fr;
  align-items: center;
  gap: var(--spacing-300);
}
.bcn-tl__row--bars {
  align-items: start;
}
.bcn-tl__row--more {
  margin-top: calc(var(--spacing-250) * -1);
}
.bcn-tl__lane-label {
  font-size: 0.8125rem;
  font-weight: var(--font-weight-semibold);
  color: var(--color-text-secondary);
}
.bcn-tl__track {
  position: relative;
  height: 30px;
}
.bcn-tl__row--axis .bcn-tl__track {
  height: 20px;
}
.bcn-tl__track--bars {
  height: 22px;
}
.bcn-tl__rule {
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  height: 1px;
  background: var(--color-border);
}
.bcn-tl__today {
  position: absolute;
  top: 0;
  bottom: -170px;
  width: 2px;
  background: var(--color-orange-400, #f9a134);
  z-index: 1;
  pointer-events: none;
}
.bcn-tl__today-flag {
  position: absolute;
  top: -2px;
  left: 4px;
  font-size: 0.75rem;
  font-weight: var(--font-weight-semibold);
  color: var(--color-orange-400, #f9a134);
}
.bcn-tl__showall {
  justify-self: start;
  padding: 0;
  font-family: inherit;
  font-size: 0.8125rem;
  font-weight: var(--font-weight-semibold);
  color: var(--color-primary);
  background: none;
  border: 0;
  cursor: pointer;
}
.bcn-tl__showall:hover {
  color: var(--color-primary-hover);
}
.bcn-tl__empty {
  margin: 0;
  font-size: var(--type-size-150);
  color: var(--color-text-tertiary);
}
.bcn-tl .bcn-tl__tick {
  position: absolute;
  top: 2px;
  transform: translate(-50%);
  font-size: 0.75rem;
  color: var(--color-text-muted);
  white-space: nowrap;
}
.bcn-tl .bcn-tl__item {
  position: absolute;
  top: 50%;
  transform: translate(-50%, -50%);
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  padding: 0;
  background: none;
  border: 0;
  cursor: pointer;
  border-radius: var(--radius-full);
}
.bcn-tl .bcn-tl__item:hover,
.bcn-tl .bcn-tl__item[data-pinned] {
  background: color-mix(in srgb, var(--color-primary) 10%, transparent);
}
.bcn-tl .bcn-tl__item:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: -2px;
}
.bcn-tl .bcn-tl__dot {
  display: block;
  width: 11px;
  height: 11px;
  border-radius: var(--radius-full);
  background: var(--color-border-strong);
  border: 2px solid var(--color-surface);
  box-shadow: 0 0 0 1px var(--color-border);
}
.bcn-tl [data-urgency="overdue"] .bcn-tl__dot {
  background: var(--color-danger);
  box-shadow: none;
}
.bcn-tl [data-urgency="due-soon"] .bcn-tl__dot {
  background: var(--color-warning);
  box-shadow: none;
}
.bcn-tl .bcn-tl__diamond {
  display: block;
  width: 11px;
  height: 11px;
  background: var(--color-info);
  transform: rotate(45deg);
}
.bcn-tl .bcn-tl__bar {
  position: absolute;
  height: 18px;
  display: flex;
  align-items: center;
  gap: var(--spacing-200);
  padding: 0 var(--spacing-150);
  background: color-mix(in srgb, var(--color-secondary) 16%, var(--color-surface));
  border: 1px solid color-mix(in srgb, var(--color-secondary) 40%, var(--color-surface));
  border-radius: var(--radius-100);
  overflow: hidden;
  cursor: pointer;
  text-align: left;
}
.bcn-tl .bcn-tl__bar:hover,
.bcn-tl .bcn-tl__bar[data-pinned] {
  background: color-mix(in srgb, var(--color-secondary) 26%, var(--color-surface));
}
.bcn-tl .bcn-tl__bar-label {
  font-size: 0.75rem;
  font-weight: var(--font-weight-semibold);
  color: var(--bcn-teal-800, var(--color-secondary-hover));
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bcn-tl .bcn-tl__bar-dates {
  margin-left: auto;
  font-size: 0.75rem;
  color: var(--color-text-tertiary);
  white-space: nowrap;
}
.bcn-tl__pop {
  position: fixed;
  z-index: 5;
  width: 19rem;
  max-width: calc(100% - 16px);
  display: flex;
  flex-direction: column;
  gap: var(--spacing-250);
  padding: var(--spacing-350, var(--spacing-300)) var(--spacing-400);
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-200);
  box-shadow: var(--shadow-300, 0 8px 24px -6px rgba(0, 0, 0, 0.18));
}
.bcn-tl__pop[hidden] {
  display: none;
}
.bcn-tl__pop-head {
  display: flex;
  align-items: center;
  gap: var(--spacing-200);
}
.bcn-tl__pop-type {
  font-size: 0.75rem;
  font-weight: var(--font-weight-semibold);
  color: var(--color-text-tertiary);
  text-transform: capitalize;
}
.bcn-tl__pop-title {
  margin: 0;
  font-size: var(--type-size-200);
  font-weight: var(--font-weight-semibold);
  color: var(--color-text-primary);
  line-height: var(--line-height-tight);
}
.bcn-tl__pop-facts {
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-200);
}
.bcn-tl__pop-facts div {
  display: grid;
  grid-template-columns: 6.5rem 1fr;
  gap: var(--spacing-200);
}
.bcn-tl__pop-facts dt {
  font-size: 0.8125rem;
  color: var(--color-text-tertiary);
}
.bcn-tl__pop-facts dd {
  margin: 0;
  font-size: 0.8125rem;
  color: var(--color-text-primary);
}
.bcn-tl__pop-late {
  font-weight: var(--font-weight-semibold);
  color: var(--color-danger);
}
.bcn-tl__pop-species {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing-150);
}
.bcn-tl__pop-chip {
  padding: 1px var(--spacing-200);
  font-size: 0.75rem;
  color: var(--color-text-secondary);
  background: var(--color-surface-sunken);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-100);
}
.bcn-tl__pop-link {
  align-self: flex-start;
  font-size: 0.8125rem;
  font-weight: var(--font-weight-semibold);
  color: var(--color-primary);
  text-decoration: none;
}
.bcn-tl__pop .bcn-cbadge {
  display: inline-block;
  font-family: var(--font-mono);
  font-weight: var(--font-weight-semibold);
  color: var(--color-commitment);
  background: color-mix(in srgb, var(--color-commitment) 12%, white);
  border-radius: var(--radius-100);
  font-size: 0.75rem;
  padding: 1px var(--spacing-150);
}

.bcn-search-trigger .esa-icon {
  flex: none;
  color: var(--color-text-tertiary);
}
.bcn-help-bar .esa-icon-button {
  color: var(--bcn-helpbar-fg-muted);
  --icon-button-bg-hover: var(--bcn-helpbar-hover-bg);
}
.bcn-help-bar .esa-icon-button:hover,
.bcn-help-bar .esa-icon-button:focus-visible {
  color: var(--bcn-helpbar-fg);
}
.bcn-gd__label .esa-icon {
  color: var(--color-text-tertiary);
  flex: none;
}
.bcn-gd-row .esa-icon {
  color: var(--color-text-tertiary);
  flex: none;
}
.topbar__right .esa-icon-button {
  color: var(--color-text-secondary);
}
.user-panel__item .esa-icon {
  color: var(--bcn-gray-500);
}
.user-panel__item--danger .esa-icon {
  color: var(--color-danger);
}
.project-switcher__trigger > .esa-icon:first-child {
  flex-shrink: 0;
  color: var(--bcn-gray-500);
}
.nav-section__header:hover .esa-icon,
.nav-section--active .nav-section__header,
.nav-section--active .nav-section__header .esa-icon {
  color: var(--color-primary);
}
.nav-section__header > .esa-icon:first-child {
  flex-shrink: 0;
  color: var(--bcn-gray-950);
  transition: color 0.15s ease;
}
.nav-section__header > .esa-icon:last-child {
  color: var(--bcn-gray-400);
  transition:
    transform 0.15s ease,
    opacity 0.2s ease-in-out;
  flex-shrink: 0;
}
.nav-section--collapsed .nav-section__header > .esa-icon:last-child {
  transform: rotate(-90deg);
}
.side-nav.collapsed .nav-section__header > .esa-icon:last-child {
  display: none;
}
.bcn-tl__pop .bcn-cbadge {
  display: inline-block;
  font-family: var(--font-mono);
  font-weight: var(--font-weight-semibold);
  color: var(--color-commitment);
  background: color-mix(in srgb, var(--color-commitment) 12%, white);
  border-radius: var(--radius-100);
  font-size: 0.75rem;
  padding: 1px var(--spacing-150);
}
.bcn-cbadge {
  display: inline-block;
  flex-shrink: 0;
  font-family: var(--font-mono);
  font-weight: var(--font-weight-semibold);
  color: var(--color-commitment);
  background: color-mix(in srgb, var(--color-commitment) 12%, white);
  border-radius: var(--radius-100);
  white-space: nowrap;
}
.bcn-cbadge--md {
  font-size: var(--type-size-100);
  padding: 1px var(--spacing-200);
}
.bcn-cbadge--sm {
  font-size: 0.75rem;
  padding: 1px var(--spacing-150);
}
.bcn-mod__grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--spacing-400);
}
.bcn-mod__card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-300);
  padding: var(--spacing-400);
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-300);
  transition:
    border-color 0.15s ease,
    box-shadow 0.15s ease;
}
.bcn-mod__card:hover {
  border-color: var(--color-border-strong);
  box-shadow: var(--shadow-50, 0 1px 4px 0 rgba(0, 0, 0, 0.05));
}
.bcn-mod__portal {
  position: absolute;
  inset: 0;
  border-radius: var(--radius-300);
}
.bcn-mod__portal:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: -2px;
}
.bcn-mod__head {
  display: flex;
  align-items: center;
  gap: var(--spacing-300);
}
.bcn-mod__glyph {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  border-radius: var(--radius-200);
  background: var(--color-surface-sunken);
  color: var(--color-text-secondary);
}
.bcn-mod__name {
  font-size: var(--type-size-300);
  font-weight: var(--font-weight-semibold);
  color: var(--color-text-primary);
}
.bcn-mod__rollup {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing-300) var(--spacing-500);
  padding-bottom: var(--spacing-300);
  border-bottom: 1px solid var(--color-border-light);
  --stat-value-size: var(--type-size-400);
  --stat-label-size: var(--type-size-150);
  --stat-label-color: var(--color-text-tertiary);
}
.bcn-mod__actions {
  position: relative;
  z-index: 1;
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-200);
}
.bcn-mod__action {
  display: flex;
  align-items: flex-start;
  gap: var(--spacing-200);
  text-decoration: none;
  color: inherit;
}
.bcn-mod__dot {
  width: 9px;
  height: 9px;
  margin-top: 5px;
  border-radius: var(--radius-full);
  background: var(--color-border-strong);
  flex-shrink: 0;
}
[data-urgency="overdue"] .bcn-mod__dot {
  background: var(--color-danger);
}
[data-urgency="due-soon"] .bcn-mod__dot {
  background: var(--color-warning);
}
.bcn-mod__action-body {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}
.bcn-mod__action-name {
  font-size: var(--type-size-150);
  font-weight: var(--font-weight-medium);
  color: var(--color-text-primary);
  line-height: var(--line-height-tight);
}
.bcn-mod__action:hover .bcn-mod__action-name {
  color: var(--color-primary);
}
.bcn-mod__action-name .bcn-cbadge {
  margin-right: var(--spacing-150);
}
.bcn-mod__action-meta {
  font-size: 0.8125rem;
  color: var(--color-text-tertiary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.bcn-mod__more {
  position: relative;
  z-index: 1;
  font-size: 0.8125rem;
  font-weight: var(--font-weight-medium);
  color: var(--color-text-secondary);
  text-decoration: none;
}
.bcn-mod__more:hover {
  color: var(--color-primary);
}
.bcn-mod__links {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-100);
  padding-top: var(--spacing-300);
